/*
 * A092260  Permutation of natural numbers generated by 6-rowed array shown
 *          below.
 * https://oeis.org/A092260
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 72, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation:  a(n) is produced by reading entries of a 6‑row infinite array
 * along the anti‑diagonals (sums of row and column indices).  
 *
 * Row k (1 ≤ k ≤ 6) is defined as:
 *   k = 1 :  a(j) = 6(j‑1) + (j odd ? 1 : 5)
 *   k = 2 :  a(j) = 6(j‑1) + (j odd ? 2 : 4)
 *   k = 3 :  a(j) = 6(j‑1) + 3
 *   k = 4 :  a(j) = 6(j‑1) + (j odd ? 4 : 2)
 *   k = 5 :  a(j) = 6(j‑1) + (j odd ? 5 : 1)
 *   k = 6 :  a(j) = 6·j
 *
 * The sequence lists the array elements in order of increasing i+j, and
 * within each diagonal the rows are taken in ascending order.
 *
 * This implementation works for any n ≥ 1 and for every build where
 * seq_t and idx_t are defined as required.
 */

seq_t a(idx_t n)
{
    /* Find the diagonal (sum of indices) that contains the n-th term. */
    idx_t sum = 0;          /* total number of terms processed so far   */
    idx_t s   = 2;          /* current diagonal: i + j = s              */

    while (1) {
        /* Number of entries on diagonal s: 1,2,3,4,5,6,6,6,...  */
        idx_t entries = (s - 1 < 6 ? s - 1 : 6);

        if (sum + entries >= n) {            /* n lies on this diagonal */
            idx_t row = n - sum;            /* 1‑based row number */
            idx_t col = s - row;            /* 1‑based column number */

            switch (row) {
                case 1:  return (seq_t)6 * (seq_t)(col - 1) +
                           ((col & 1) ? 1 : 5);
                case 2:  return (seq_t)6 * (seq_t)(col - 1) +
                           ((col & 1) ? 2 : 4);
                case 3:  return (seq_t)6 * (seq_t)(col - 1) + 3;
                case 4:  return (seq_t)6 * (seq_t)(col - 1) +
                           ((col & 1) ? 4 : 2);
                case 5:  return (seq_t)6 * (seq_t)(col - 1) +
                           ((col & 1) ? 5 : 1);
                case 6:  return (seq_t)6 * (seq_t)col;   /* 6·j  */
                default: return (seq_t)0;                 /* never reached */
            }
        }

        /* Move to the next diagonal. */
        sum += entries;
        ++s;
    }
}
